use lean_runtime::semantics::float32;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &Vec<f64>, n: u64) -> u64 {
    let xs = &inp[..];
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(acc, {
            let (m, e) = float32::frexp((get_f64(xs, x >> 52) as f32));
            gbits(m) ^ (e as i64 as u64)
        });
    }
    acc
}

fn main() {
    run(
        || f64_operands(0xC12E848000000000, 0x413E848000000000, true),
        kernel,
    )
}
